"""Assemble article/article.md + site/visuals/*.svg + site/motion.js into
site/index.html (GitHub Pages) and README.md (static, SVGs as <img>)."""
import re, pathlib, markdown

ROOT = pathlib.Path(__file__).resolve().parent.parent
SITE = ROOT / "docs"
md = (ROOT / "article/article.md").read_text()
MARK = re.compile(r"^<!--\s*visual:([a-z-]+)\s*-->\s*$", re.M)

title = re.search(r"^#\s+(.+)$", md, re.M).group(1).strip()

# README: static images, relative to repo root
readme = MARK.sub(lambda m: f'<p align="center"><img src="docs/visuals/{m.group(1)}.svg" alt="{m.group(1)} diagram" width="760"></p>', md)
readme = readme.replace("](research/", "](research/")
banner = "> **Animated version:** https://wilsonwu-ai.github.io/anthropic-ipo-explained/\n\n"
readme = re.sub(r"^(#\s+.+\n)", lambda m: m.group(1) + "\n" + banner, readme, count=1, flags=re.M)
(ROOT / "README.md").write_text(readme)

# Page: inline SVGs inside figures so motion.js can reach them
def figure(m):
    name = m.group(1)
    svg = (SITE / "visuals" / f"{name}.svg").read_text()
    svg = re.sub(r"<\?xml[^>]*\?>", "", svg).strip()
    # Each standalone SVG carries its own dark-mode brand block for direct viewing; the page has one
    # scoped per chart (wilson.md brand block in the head), so drop the SVG's copy when inlining.
    svg = re.sub(r"<!-- wilson\.md brand -->.*?<!-- /wilson\.md brand -->\n?", "", svg, flags=re.S)
    return f'\n<figure data-visual="{name}">{svg}</figure>\n'

body_md = MARK.sub(figure, md)
body_md = re.sub(r"\]\(facts/", "](https://github.com/wilsonwu-ai/anthropic-ipo-explained/blob/main/facts/", body_md)
html_body = markdown.markdown(body_md, extensions=["tables", "fenced_code", "sane_lists", "md_in_html"])
html_body = html_body.replace("<a href=\"http", "<a target=\"_blank\" rel=\"noopener\" href=\"http")

page = f"""<!doctype html>
<html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title}</title>
<meta name="description" content="What the Anthropic S-1 reveals about how the AI industry makes money, what it costs, and why AI software runs on hardware.">
<style>
:root{{--bg:#f5f7fa;--ink:#14212f;--muted:#4c5a6b;--rule:#d5dce5;--accent:#a8481b;--card:#ffffff;--quote:#e6ecf3}}
@media (prefers-color-scheme:dark){{:root:not([data-theme=light]){{--bg:#081420;--ink:#e8edf3;--muted:#9daec0;--rule:#22384f;--accent:#ee9264;--card:#0e2238;--quote:#13304f}}}}
:root[data-theme=dark]{{--bg:#081420;--ink:#e8edf3;--muted:#9daec0;--rule:#22384f;--accent:#ee9264;--card:#0e2238;--quote:#13304f}}
*{{box-sizing:border-box}}
body{{margin:0;background:var(--bg);color:var(--ink);font:18px/1.65 "Benton Sans", BentonSans, "Public Sans", "Helvetica Neue", Arial, sans-serif}}
main{{max-width:760px;margin:0 auto;padding:48px 16px 96px}}
h1{{font-size:clamp(30px,6vw,46px);line-height:1.1;letter-spacing:-.02em;margin:0 0 12px}}
h2{{font-size:clamp(22px,4.2vw,30px);line-height:1.2;margin:64px 0 12px;padding-top:16px;border-top:1px solid var(--rule)}}
h3{{font-size:19px;margin:28px 0 6px}}
a{{color:var(--accent);text-underline-offset:2px}}
blockquote{{margin:20px 0;padding:14px 18px;background:var(--quote);border-left:4px solid var(--accent);border-radius:6px}}
blockquote p{{margin:.3em 0}}
figure{{margin:28px -8px;padding:8px;background:var(--card);border:1px solid var(--rule);border-radius:12px}}
figure svg{{display:block;width:100%;height:auto;border-radius:8px}}
@media (max-width:640px){{figure{{overflow-x:auto;-webkit-overflow-scrolling:touch}}figure svg{{width:700px;max-width:none}}figure::after{{content:"swipe to see the whole picture";display:block;font-size:13px;color:var(--muted);padding:6px 4px 0;position:sticky;left:0}}}}
table{{border-collapse:collapse;width:100%;font-size:16px;display:block;overflow-x:auto}}
th,td{{text-align:left;padding:8px 10px;border-bottom:1px solid var(--rule);vertical-align:top}}
code{{font-size:.9em}}
hr{{border:0;border-top:1px solid var(--rule);margin:40px 0}}
</style><!-- wilson.md brand -->
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Public+Sans:ital,wght@0,300..800;1,300..800&display=swap">
<link rel="stylesheet" href="wilson.css">
<style>@media (prefers-color-scheme: dark){{html svg{{--cons:#EE9264;--subs:#A9C2E3;--hw:#4FC3C0;--neu:#6A82A0;--loss:#F27D74;--pos:#5FC38A;--on:#081420;--api:#EE9264;--sub:#A9C2E3;--neutral:#6A82A0;--cash:#5FC38A}}}}figure[data-visual="plans"] :is(.val,.name),figure[data-visual="commitments"] :is(.val,.name){{text-anchor:start}}@media (prefers-color-scheme: dark){{figure[data-visual="loss-bridge"] text.vw{{fill:#081420}}}}/* chart-isolation: each inline chart renders as its standalone svg (generated by svg_restore.py) */@keyframes wb-commitments-grow{{0% {{ transform: scaleX(0); }} 100% {{ transform: scaleX(1); }}}}@keyframes wb-plans-grow{{0% {{ transform: scaleX(0); }} 100% {{ transform: scaleX(1); }}}}@keyframes wb-stack-rise{{0% {{ transform: translateY(-14px); opacity: 0; }} 100% {{ transform: translateY(0px); opacity: 1; }}}}figure[data-visual="commitments"] rect.bar.firm{{transform-origin:0 50%}}figure[data-visual="commitments"] rect.bar.ref{{transform-origin:0 50%}}figure[data-visual="commitments"] rect.bar.soft{{transform-origin:0 50%}}figure[data-visual="commitments"] text.val{{font-size:16px}}figure[data-visual="loss-bridge"] text.name{{font-weight:400}}figure[data-visual="loss-bridge"] text.note{{fill:var(--ink,#14212f);font-size:15px}}figure[data-visual="loss-bridge"] text.title{{font-size:26px}}figure[data-visual="loss-bridge"] text.vl{{fill:var(--loss,#b3261e);text-anchor:start}}figure[data-visual="plans"] circle.dot.down{{stroke:none;stroke-width:1px}}figure[data-visual="plans"] circle.dot.flat{{stroke:none;stroke-width:1px}}figure[data-visual="plans"] circle.dot.up{{stroke:none;stroke-width:1px}}figure[data-visual="plans"] rect.bar.apibar{{transform-origin:0 50%}}figure[data-visual="plans"] text.val{{font-size:16px}}figure[data-visual="quarterly"] text.note{{fill:var(--ink,#14212f);font-size:15px}}figure[data-visual="quarterly"] text.title{{font-size:26px}}figure[data-visual="quarterly"] text.val{{font-size:15px}}figure[data-visual="revenue-mix"] text.big{{fill:var(--cons,#a8481b);font-size:44px}}figure[data-visual="revenue-mix"] text.title{{font-size:26px}}figure[data-visual="stack"] text.big{{fill:var(--hw,#0f6f72);font-size:30px}}figure[data-visual="stack"] text.title{{font-size:26px}}figure[data-visual="valuation"] text.axis{{stroke:none;stroke-width:1px}}figure[data-visual="commitments"] svg.play rect.bar.firm{{animation-name:wb-commitments-grow}}figure[data-visual="commitments"] svg.play rect.bar.ref{{animation-name:wb-commitments-grow;animation-duration:1.2s}}figure[data-visual="commitments"] svg.play rect.bar.soft{{animation-name:wb-commitments-grow}}figure[data-visual="plans"] svg.play rect.bar.apibar{{animation-name:wb-plans-grow;animation-duration:1.4s}}figure[data-visual="quarterly"] svg.play text.val{{animation-name:none}}figure[data-visual="stack"] svg.play g.layer{{animation-name:wb-stack-rise}}/* end chart-isolation */</style><!-- /wilson.md brand -->
</head>
<body><main>
{html_body}
</main>
<script src="motion.js"></script>
</body></html>
"""
(SITE / "index.html").write_text(page)
print("built", len(md.split()), "words;", len(MARK.findall(md)), "visuals")
